        TIMESTAMP '2026-04-15 15:00:00',
        'Workshops & Training',
        'SCHEDULED'::event_status
    WHERE NOT EXISTS (SELECT 1 FROM existing_event)
    RETURNING event_id
),
resolved_event AS (
